					career : false,
					yearsofservice : false,
					totalassets : false,
					totalliabilities : false,
					debtratio : false,
					creditlimit : false,
					creditcardusagerate : false,
					creditscore : false,
					credithistorylength : false,
					numberofoverduetimes : false,
					seriousoverduetimes : false,
					overdueamount : false,
					overduedays : false,
					creditinquiryfrequency : false,
					loanamount : false,
					loanterm : false,
					lendingrate : false,
					repaymentmethod : false,
					loanpurpose : false,
					remainingloanterm : false,
				},
				type: '',
				userTableName: localStorage.getItem('UserTableName'),
				ruleForm: {
					number: '',
					gender: '',
					age: '',
					area: '',
					educationlevel: '',
					maritalstatus: '',
					householdsize: '',
					annualincome: '',
					monthlyincome: '',
					career: '',
					yearsofservice: '',
					totalassets: '',
					totalliabilities: '',
					debtratio: '',
					creditlimit: '',
					creditcardusagerate: '',
					creditscore: '',
					credithistorylength: '',
					numberofoverduetimes: '',
					seriousoverduetimes: '',
					overdueamount: '',
					overduedays: '',
					creditinquiryfrequency: '',
					loanamount: '',
					loanterm: '',
					lendingrate: '',
					repaymentmethod: '',
					loanpurpose: '',
					remainingloanterm: '',
				},


				rules: {
					number: [
						{ required: true, message: '编号不能为空', trigger: 'blur' },
					],
					gender: [
					],
					age: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					area: [
					],
					educationlevel: [
					],
					maritalstatus: [
					],
					householdsize: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					annualincome: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					monthlyincome: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					career: [
					],
					yearsofservice: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					totalassets: [
						{ validator: this.$validate.isNumber, trigger: 'blur' },
					],
					totalliabilities: [
						{ validator: this.$validate.isNumber, trigger: 'blur' },
					],
					debtratio: [
					],
					creditlimit: [
						{ validator: this.$validate.isNumber, trigger: 'blur' },
					],
					creditcardusagerate: [
					],
					creditscore: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					credithistorylength: [
					],
					numberofoverduetimes: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					seriousoverduetimes: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					overdueamount: [
						{ validator: this.$validate.isNumber, trigger: 'blur' },
					],
					overduedays: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					creditinquiryfrequency: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					loanamount: [
						{ validator: this.$validate.isNumber, trigger: 'blur' },
					],
					loanterm: [
					],
					lendingrate: [
					],
					repaymentmethod: [
					],
					loanpurpose: [
					],
					remainingloanterm: [
					],
				},
				centerType: false,
			};
		},
		computed: {



		},
		components: {
		},
		created() {
			if(this.$route.query.centerType){
				this.centerType = true
			}
			//this.bg();
			let type = this.$route.query.type ? this.$route.query.type : '';
			this.init(type);
			this.baseUrl = this.$config.baseUrl;
		},
		methods: {
			getMakeZero(s) {
				return s < 10 ? '0' + s : s;
			},
			// 下载
			download(file){
				window.open(`${file}`)
			},
			// 初始化
			init(type) {
				this.type = type;
				if(type=='cross'){
					var obj = JSON.parse(localStorage.getItem('crossObj'));
					for (var o in obj){
						if(o=='number'){
							this.ruleForm.number = obj[o];
							this.ro.number = true;
							continue;
						}
						if(o=='gender'){
							this.ruleForm.gender = obj[o];
							this.ro.gender = true;
							continue;
						}
						if(o=='age'){
							this.ruleForm.age = obj[o];
							this.ro.age = true;
							continue;
						}
						if(o=='area'){
							this.ruleForm.area = obj[o];
							this.ro.area = true;
							continue;
						}
						if(o=='educationlevel'){
							this.ruleForm.educationlevel = obj[o];
							this.ro.educationlevel = true;
							continue;
						}
						if(o=='maritalstatus'){
							this.ruleForm.maritalstatus = obj[o];
							this.ro.maritalstatus = true;
							continue;
						}
						if(o=='householdsize'){
							this.ruleForm.householdsize = obj[o];
							this.ro.householdsize = true;
							continue;
						}
						if(o=='annualincome'){
							this.ruleForm.annualincome = obj[o];
							this.ro.annualincome = true;
							continue;
						}
						if(o=='monthlyincome'){
							this.ruleForm.monthlyincome = obj[o];
							this.ro.monthlyincome = true;
							continue;
						}
						if(o=='career'){
							this.ruleForm.career = obj[o];
							this.ro.career = true;
							continue;
						}
						if(o=='yearsofservice'){
							this.ruleForm.yearsofservice = obj[o];
							this.ro.yearsofservice = true;
							continue;
						}
						if(o=='totalassets'){
							this.ruleForm.totalassets = obj[o];
							this.ro.totalassets = true;
							continue;
						}
						if(o=='totalliabilities'){
							this.ruleForm.totalliabilities = obj[o];
							this.ro.totalliabilities = true;
							continue;
						}
						if(o=='debtratio'){
							this.ruleForm.debtratio = obj[o];
							this.ro.debtratio = true;
							continue;
						}
						if(o=='creditlimit'){
							this.ruleForm.creditlimit = obj[o];
							this.ro.creditlimit = true;
							continue;
						}
						if(o=='creditcardusagerate'){
							this.ruleForm.creditcardusagerate = obj[o];
							this.ro.creditcardusagerate = true;
							continue;
						}
						if(o=='creditscore'){
							this.ruleForm.creditscore = obj[o];
							this.ro.creditscore = true;
							continue;
						}
						if(o=='credithistorylength'){
							this.ruleForm.credithistorylength = obj[o];
							this.ro.credithistorylength = true;
							continue;
						}
						if(o=='numberofoverduetimes'){
							this.ruleForm.numberofoverduetimes = obj[o];
							this.ro.numberofoverduetimes = true;
							continue;
						}
						if(o=='seriousoverduetimes'){
							this.ruleForm.seriousoverduetimes = obj[o];
							this.ro.seriousoverduetimes = true;
							continue;
						}
						if(o=='overdueamount'){
							this.ruleForm.overdueamount = obj[o];
							this.ro.overdueamount = true;
							continue;
						}
						if(o=='overduedays'){
							this.ruleForm.overduedays = obj[o];
							this.ro.overduedays = true;
							continue;
						}
						if(o=='creditinquiryfrequency'){
							this.ruleForm.creditinquiryfrequency = obj[o];
							this.ro.creditinquiryfrequency = true;
							continue;
						}
						if(o=='loanamount'){
							this.ruleForm.loanamount = obj[o];
							this.ro.loanamount = true;
							continue;
						}
						if(o=='loanterm'){
							this.ruleForm.loanterm = obj[o];
							this.ro.loanterm = true;
							continue;
						}
						if(o=='lendingrate'){
							this.ruleForm.lendingrate = obj[o];
							this.ro.lendingrate = true;
							continue;
						}
						if(o=='repaymentmethod'){
							this.ruleForm.repaymentmethod = obj[o];
							this.ro.repaymentmethod = true;
							continue;
						}
						if(o=='loanpurpose'){
							this.ruleForm.loanpurpose = obj[o];
							this.ro.loanpurpose = true;
							continue;
						}
						if(o=='remainingloanterm'){
							this.ruleForm.remainingloanterm = obj[o];
							this.ro.remainingloanterm = true;
							continue;
						}
					}
				}else if(type=='edit'){
					this.info()
				}
				// 获取用户信息
				this.$http.get(this.userTableName + '/session', {emulateJSON: true}).then(res => {
					if (res.data.code == 0) {
						var json = res.data.data;
					}
				});

				if (localStorage.getItem('raffleType') && localStorage.getItem('raffleType') != null) {
					localStorage.removeItem('raffleType')
					setTimeout(() => {
						this.onSubmit()
					}, 300)
				}
			},

			// 多级联动参数
			// 多级联动参数
			info() {
				this.$http.get(`creditdata/detail/${this.$route.query.id}`, {emulateJSON: true}).then(res => {
					if (res.data.code == 0) {
						this.ruleForm = res.data.data;
					}
				});
			},
			// 提交
			async onSubmit() {
				if(!this.ruleForm.id) {
					delete this.ruleForm.userid
				}
				await this.$refs["ruleForm"].validate(async valid => {
					if(valid) {
						if(this.type=='cross'){
							var statusColumnName = localStorage.getItem('statusColumnName');
							var statusColumnValue = localStorage.getItem('statusColumnValue');
							if(statusColumnName && statusColumnName!='') {
								var obj = JSON.parse(localStorage.getItem('crossObj'));
								if(!statusColumnName.startsWith("[")) {
									for (var o in obj){
										if(o==statusColumnName){
											obj[o] = statusColumnValue;
										}
									}
									var table = localStorage.getItem('crossTable');
									await this.$http.post(table+'/update', obj).then(res => {});
								}
							}
						}


						await this.$http.post(`creditdata/${this.ruleForm.id?'update':this.centerType?'save':'add'}`, this.ruleForm).then(async res => {
							if (res.data.code == 0) {
								this.$message({
									message: '操作成功',
									type: 'success',
									duration: 1500,
									onClose: () => {
										this.$router.go(-1);
										
									}
								});
							} else {
								this.$message({
									message: res.data.msg,
									type: 'error',
									duration: 1500
								});
							}
						});
					}
				});
			},
			// 获取uuid
			getUUID () {
				return new Date().getTime();
			},
			// 返回
			back() {
				this.$router.go(-1);
			},
		}
	};
</script>

